local event = require('event') local comp = require('component') local robot = require('robot') local inv = comp.inventory_controller local function getFixedItem() while 1 do local item = inv.getStackInSlot(3, 1) if not item or item.damage > 1 then os.sleep(1) else inv.suckFromSlot(3, 1) break end end end local function fixHoeIfNeeded() inv.equip() local item = inv.getStackInInternalSlot() if item and item.damage < 100 then inv.equip() return end robot.turnRight() inv.dropIntoSlot(3, 1) getFixedItem() inv.equip() robot.turnLeft() end local function hasFreeSpace() return robot.space(robot.inventorySize()) == 64 and robot.space(robot.inventorySize() - 1) == 64 end local function placeSeed() for k=1,robot.inventorySize() do local item = inv.getStackInInternalSlot(k) if item and item.name == 'ThaumicTinkerer:infusedSeeds' then robot.select(k) robot.place() break end end print('No seed dropped') end local function dropAll() for k=1,robot.inventorySize() do robot.select(k) while inv.getStackInInternalSlot() and not inv.dropIntoSlot(3, k) do end end end while 1 do robot.select(1) robot.use() robot.swing() placeSeed() if not hasFreeSpace() then robot.turnAround() dropAll() robot.turnAround() end fixHoeIfNeeded() end